node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get current cart and item details
const item = db.prepare(\"SELECT * FROM cart_items WHERE cart_item_id = 'CI-0005'\").get();
console.log('Removing item:', JSON.stringify(item, null, 2));

// Get product price to recalculate
const prod = db.prepare(\"SELECT price FROM products WHERE product_id = ?\").get(item.product_id);
const itemTotal = prod.price * item.quantity;
console.log('Item cost to remove:', itemTotal);

// Remove the cart item
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005'\").run();

// Update the cart: remove CI-0005 from item_ids_json and update subtotal/total
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
const itemIds = JSON.parse(cart.item_ids_json).filter(id => id !== 'CI-0005');
const newSubtotal = cart.subtotal - itemTotal;
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;

db.prepare(\"UPDATE carts SET item_ids_json = ?, subtotal = ?, total = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(
  JSON.stringify(itemIds), newSubtotal, newTotal
);

// Verify updated cart
const updatedCart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log('\\nUpdated cart:', JSON.stringify(updatedCart, null, 2));

const remainingItems = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
console.log('\\nRemaining items:', JSON.stringify(remainingItems, null, 2));

// Check shipping options - look at user's prime status and any shipping config
const user = db.prepare(\"SELECT has_prime_shipping FROM users WHERE user_id = 'user_58b0a2d6'\").get();
console.log('\\nHas prime shipping:', user.has_prime_shipping);

// Check if there are shipping-related tables or promotions
const promos = db.prepare(\"SELECT * FROM promotions\").all();
console.log('\\nPromotions:', JSON.stringify(promos, null, 2));
"

